<template><AsyncState :loading="loading" :error="error" :retry-label="t('btn.retry')" @retry="$emit('retry')"><main class="page"><PageHeader :title="t('nav.services')"><template #primary><button data-action="refresh-services" :disabled="loading" @click="$emit('refresh')">{{t('btn.refresh')}}</button></template></PageHeader><SectionCard><div v-if="services.length" class="grid"><article v-for="s in services" :key="s.name" :data-service="s.name"><header><h3>{{s.name}}</h3><StatusBadge :tone="s.status==='running'?'success':'neutral'"><template #icon><span aria-hidden="true">●</span></template>{{s.status}}</StatusBadge></header><p>{{s.type}} <span v-if="s.version">v{{s.version}}</span></p><p v-if="s.port">Port: {{s.port}}</p><button v-if="s.status!=='running'" data-action="start-service" :disabled="!!operating[s.name]" @click="$emit('start',s.name)">{{t('services.start')}}</button><ConfirmAction v-else :title="t('services.stop')" :pending="!!operating[s.name]" @confirm="$emit('stop',s.name)"><template #trigger><button data-action="stop-service" :disabled="!!operating[s.name]">{{t('services.stop')}}</button></template></ConfirmAction></article></div><p v-else>{{t('services.empty')}}</p></SectionCard></main></AsyncState></template>
<script setup>import AsyncState from'../components/AsyncState.vue';import ConfirmAction from'../components/ConfirmAction.vue';import PageHeader from'../components/PageHeader.vue';import SectionCard from'../components/SectionCard.vue';import StatusBadge from'../components/StatusBadge.vue';defineProps({services:{type:Array,default:()=>[]},operating:{type:Object,default:()=>({})},loading:Boolean,error:{type:[String,Error],default:null},t:{type:Function,required:true}});defineEmits(['refresh','start','stop','retry']);</script>
<style scoped>.page{display:grid;gap:16px;min-width:0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(260px,100%),1fr));gap:12px}article{padding:16px;border:1px solid var(--xdev-border-subtle);border-radius:8px}header{display:flex;align-items:center;justify-content:space-between;gap:8px}h3{margin:0}</style>
